<?php
session_start();
header('Content-Type: application/json; charset=utf-8');
header('Cache-Control: no-store');
require_once __DIR__.'/database/connect.php';
require_once __DIR__.'/auth.php';

function aok($data=null,$message=''){echo json_encode(['ok'=>true,'data'=>$data,'message'=>$message],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function afail($m,$s=400){http_response_code($s);echo json_encode(['ok'=>false,'message'=>$m],JSON_UNESCAPED_UNICODE);exit;}
function adata(){ $raw=file_get_contents('php://input'); $j=json_decode($raw?:'{}',true); return is_array($j)?$j:$_POST; }
function aall(mysqli_result $r){return $r->fetch_all(MYSQLI_ASSOC);} 
function managerLike(){return in_array(currentLibraryRoleKey(),['admin','manager','employee'],true);} 
function audit(mysqli $c,string $action,string $object='',string $detail=''):void{
 $uid=(int)($_SESSION['user_id']??0);$name=(string)($_SESSION['display_name']??$_SESSION['username']??'');$role=currentLibraryRoleKey();$ip=$_SERVER['REMOTE_ADDR']??'';
 $s=$c->prepare("INSERT INTO nhatkyhoatdong(MaTaiKhoan,NguoiThucHien,VaiTro,HanhDong,DoiTuong,ChiTiet,DiaChiIP) VALUES(NULLIF(?,0),?,?,?,?,?,?)");
 $s->bind_param('issssss',$uid,$name,$role,$action,$object,$detail,$ip);$s->execute();
}
function currentReaderId():int{return (int)($_SESSION['reader_id']??0);} function currentEmployeeId():int{return (int)($_SESSION['employee_id']??0);} 
if(empty($_SESSION['user_id'])) afail('Vui lòng đăng nhập.',401);
