 $top=aall($conn->query("SELECT s.MaSach,s.TenSach,s.TacGia,s.HinhAnh,COALESCE(t.TenTheLoai,'Chưa phân loại') TenTheLoai,COALESCE(SUM(ct.SoLuong),0) LuotMuon FROM sach s LEFT JOIN theloai t ON t.MaTheLoai=s.MaTheLoai LEFT JOIN chitietphieumuon ct ON ct.MaSach=s.MaSach GROUP BY s.MaSach,s.TenSach,s.TacGia,s.HinhAnh,t.TenTheLoai ORDER BY LuotMuon DESC,s.MaSach DESC LIMIT 5"));
 $cats=aall($conn->query("SELECT COALESCE(t.TenTheLoai,'Chưa phân loại') TenTheLoai,COUNT(DISTINCT s.MaSach) SoDauSach,COALESCE(SUM(s.SoLuong),0) TongSoLuong,COALESCE(SUM(ct.SoLuong),0) LuotMuon FROM sach s LEFT JOIN theloai t ON t.MaTheLoai=s.MaTheLoai LEFT JOIN chitietphieumuon ct ON ct.MaSach=s.MaSach GROUP BY t.MaTheLoai,t.TenTheLoai ORDER BY LuotMuon DESC,TongSoLuong DESC LIMIT 6"));
 $trend=aall($conn->query("SELECT DATE(NgayMuon) Ngay,COUNT(*) Luot FROM phieumuon WHERE NgayMuon>=DATE_SUB(CURDATE(),INTERVAL 29 DAY) GROUP BY DATE(NgayMuon) ORDER BY Ngay"));
