   $returned=(int)$conn->query("SELECT COUNT(*) c FROM phieumuon WHERE DATE(NgayTra)='$safe'")->fetch_assoc()['c'];
   $overdue=(int)$conn->query("SELECT COUNT(*) c FROM phieumuon WHERE DATE(HanTra)='$safe' AND (NgayTra IS NULL OR DATE(NgayTra)>HanTra) AND COALESCE(TrangThai,'') NOT IN('Đã hủy','Hủy')")->fetch_assoc()['c'];
