 $activity=[];
 $check=$conn->query("SHOW TABLES LIKE 'nhatkyhoatdong'");
 if($check && $check->num_rows){
   $activity=aall($conn->query("SELECT MaNhatKy,NguoiThucHien,VaiTro,HanhDong,DoiTuong,ChiTiet,NgayTao FROM nhatkyhoatdong ORDER BY MaNhatKy DESC LIMIT 12"));
 }
 aok(['days'=>$days,'today'=>$today,'activity'=>$activity,'system'=>['database'=>'Đã kết nối','php'=>PHP_VERSION,'serverTime'=>date('d/m/Y H:i:s')]]);

case 'copies':
