 $s=$conn->prepare("SELECT c.MaCuon,c.MaVach,c.TrangThai,c.MaSach,s.TenSach,s.SoLuong FROM cuonsach c JOIN sach s ON s.MaSach=c.MaSach WHERE c.MaVach=? LIMIT 1");$s->bind_param('s',$code);$s->execute();$r=$s->get_result()->fetch_assoc(); if(!$r) afail('Không tìm thấy mã độc giả/cuốn sách.',404);aok(['type'=>'copy','item'=>$r]);

case 'quick_borrow':
 if(!managerLike()) afail('Bạn không có quyền tạo phiếu mượn nhanh.',403);
 $rid=(int)($d['readerId']??0);$codes=array_values(array_unique(array_filter($d['codes']??[]))); if(!$rid||!$codes) afail('Cần chọn độc giả và ít nhất 1 cuốn sách.');
 $cfg=$conn->query("SELECT COALESCE(SoNgayMuon,14) SoNgayMuon FROM caidat ORDER BY MaCaiDat LIMIT 1")->fetch_assoc();$days=max(1,(int)($cfg['SoNgayMuon']??14));$emp=currentEmployeeId();$today=date('Y-m-d');$due=date('Y-m-d',strtotime("+$days days"));
 $conn->begin_transaction();try{
