   $bookGroups=[];$copyRows=[];$find=$conn->prepare("SELECT MaCuon,MaSach,TrangThai FROM cuonsach WHERE MaVach=? FOR UPDATE");
   foreach($codes as $code){$find->bind_param('s',$code);$find->execute();$row=$find->get_result()->fetch_assoc();if(!$row||$row['TrangThai']!=='Có sẵn') throw new Exception("Cuốn $code không còn sẵn.");$bookGroups[(int)$row['MaSach']][]=$row;}
   foreach($bookGroups as $bookId=>$copies){$qty=count($copies);$chk=$conn->prepare("SELECT SoLuong FROM sach WHERE MaSach=? FOR UPDATE");$chk->bind_param('i',$bookId);$chk->execute();$available=(int)$chk->get_result()->fetch_assoc()['SoLuong'];if($available<$qty) throw new Exception('Số lượng sách khả dụng không đủ.');$ct=$conn->prepare("INSERT INTO chitietphieumuon(MaPhieuMuon,MaSach,SoLuong,TienPhat) VALUES(?,?,?,0)");$ct->bind_param('iii',$loan,$bookId,$qty);$ct->execute();$ctid=$conn->insert_id;$u=$conn->prepare("UPDATE sach SET SoLuong=SoLuong-? WHERE MaSach=?");$u->bind_param('ii',$qty,$bookId);$u->execute();foreach($copies as $cr){$cid=(int)$cr['MaCuon'];$conn->query("UPDATE cuonsach SET TrangThai='Đang mượn' WHERE MaCuon=$cid");$lk=$conn->prepare("INSERT INTO chitietcuonmuon(MaCTPM,MaCuon) VALUES(?,?)");$lk->bind_param('ii',$ctid,$cid);$lk->execute();}}
   $conn->commit();audit($conn,'Mượn nhanh','Phiếu #'.$loan,implode(', ',$codes));aok(['loanId'=>$loan,'dueDate'=>$due],'Đã tạo phiếu mượn nhanh.');
 }catch(Throwable $e){$conn->rollback();afail($e->getMessage());}

case 'quick_return':
 if(!managerLike()) afail('Bạn không có quyền trả sách nhanh.',403);$codes=array_values(array_unique(array_filter($d['codes']??[])));if(!$codes) afail('Chưa có mã cuốn sách.');
 $done=[];$conn->begin_transaction();try{foreach($codes as $code){$s=$conn->prepare("SELECT c.MaCuon,c.MaSach,l.MaCTPM,ct.MaPhieuMuon FROM cuonsach c JOIN chitietcuonmuon l ON l.MaCuon=c.MaCuon JOIN chitietphieumuon ct ON ct.MaCTPM=l.MaCTPM JOIN phieumuon pm ON pm.MaPhieuMuon=ct.MaPhieuMuon WHERE c.MaVach=? AND c.TrangThai='Đang mượn' AND pm.NgayTra IS NULL ORDER BY pm.MaPhieuMuon DESC LIMIT 1");$s->bind_param('s',$code);$s->execute();$r=$s->get_result()->fetch_assoc();if(!$r) throw new Exception("Không tìm thấy lượt mượn đang mở cho $code.");$cid=(int)$r['MaCuon'];$bid=(int)$r['MaSach'];$loan=(int)$r['MaPhieuMuon'];$conn->query("UPDATE cuonsach SET TrangThai='Có sẵn' WHERE MaCuon=$cid");$conn->query("UPDATE sach SET SoLuong=SoLuong+1 WHERE MaSach=$bid");$remaining=$conn->query("SELECT COUNT(*) c FROM chitietcuonmuon l JOIN chitietphieumuon ct ON ct.MaCTPM=l.MaCTPM JOIN cuonsach c ON c.MaCuon=l.MaCuon WHERE ct.MaPhieuMuon=$loan AND c.TrangThai='Đang mượn'")->fetch_assoc()['c'];if((int)$remaining===0)$conn->query("UPDATE phieumuon SET NgayTra=CURDATE(),TrangThai='Đã trả' WHERE MaPhieuMuon=$loan");$done[]=$code;}
 $conn->commit();audit($conn,'Trả nhanh','Cuốn sách',implode(', ',$done));aok(['returned'=>$done],'Đã ghi nhận trả sách.');}catch(Throwable $e){$conn->rollback();afail($e->getMessage());}

