 if($rid){$r=$conn->prepare("SELECT MaYeuCau,MaPhieuMuon,TrangThai,HanTraMoi,LyDoTuChoi,NgayXuLy FROM yeucaugiahan WHERE MaDocGia=? AND TrangThai<>'Chờ duyệt' AND NgayXuLy IS NOT NULL AND NgayXuLy>=DATE_SUB(NOW(),INTERVAL 30 DAY) ORDER BY NgayXuLy DESC LIMIT 10");$r->bind_param('i',$rid);$r->execute();foreach(aall($r->get_result()) as $x){$approved=$x['TrangThai']==='Đã duyệt';$title=$approved?'Yêu cầu gia hạn đã được duyệt':'Yêu cầu gia hạn đã được xử lý';$content=$approved?'Phiếu #'.$x['MaPhieuMuon'].' được gia hạn đến '.date('d/m/Y',strtotime($x['HanTraMoi'])).'.':'Phiếu #'.$x['MaPhieuMuon'].' có trạng thái '.$x['TrangThai'].(!empty($x['LyDoTuChoi'])?' • '.$x['LyDoTuChoi']:'');$chk=$conn->prepare("SELECT 1 FROM thongbao WHERE MaTaiKhoan=? AND TieuDe=? AND NoiDung=? LIMIT 1");$chk->bind_param('iss',$uid,$title,$content);$chk->execute();if(!$chk->get_result()->fetch_assoc()){$type=$approved?'success':'warning';$in=$conn->prepare("INSERT INTO thongbao(MaTaiKhoan,MaDocGia,TieuDe,NoiDung,Loai,DuongDan) VALUES(?,?,?,?,?,'muontra.php')");$in->bind_param('iisss',$uid,$rid,$title,$content,$type);$in->execute();}}}
 if($rid){$r=$conn->prepare("SELECT dl.MaDatLich,dl.TrangThai,dl.NgayXuLy,s.TenSach,s.SoLuong FROM datlichmuon dl JOIN sach s ON s.MaSach=dl.MaSach WHERE dl.MaDocGia=? AND dl.TrangThai<>'Chờ xác nhận' AND COALESCE(dl.NgayXuLy,dl.NgayDat)>=DATE_SUB(NOW(),INTERVAL 30 DAY) ORDER BY COALESCE(dl.NgayXuLy,dl.NgayDat) DESC LIMIT 10");$r->bind_param('i',$rid);$r->execute();foreach(aall($r->get_result()) as $x){$title='Cập nhật đặt trước sách';$content=$x['TenSach'].' • '.$x['TrangThai'].((int)$x['SoLuong']>0?' • Hiện đang có sách':'');$chk=$conn->prepare("SELECT 1 FROM thongbao WHERE MaTaiKhoan=? AND TieuDe=? AND NoiDung=? LIMIT 1");$chk->bind_param('iss',$uid,$title,$content);$chk->execute();if(!$chk->get_result()->fetch_assoc()){$type=(int)$x['SoLuong']>0?'success':'info';$in=$conn->prepare("INSERT INTO thongbao(MaTaiKhoan,MaDocGia,TieuDe,NoiDung,Loai,DuongDan) VALUES(?,?,?,?,?,'muontra.php')");$in->bind_param('iisss',$uid,$rid,$title,$content,$type);$in->execute();}}}
 if($rid){$r=$conn->prepare("SELECT t.TenTheLoai,COUNT(*) c FROM phieumuon pm JOIN chitietphieumuon ct ON ct.MaPhieuMuon=pm.MaPhieuMuon JOIN sach s ON s.MaSach=ct.MaSach JOIN theloai t ON t.MaTheLoai=s.MaTheLoai WHERE pm.MaDocGia=? GROUP BY t.MaTheLoai,t.TenTheLoai ORDER BY SUM(ct.SoLuong) DESC LIMIT 1");$r->bind_param('i',$rid);$r->execute();if($x=$r->get_result()->fetch_assoc()){$title='Gợi ý mới dành cho bạn';$content='Có thêm gợi ý dựa trên thể loại '.$x['TenTheLoai'].' bạn thường đọc.';$chk=$conn->prepare("SELECT 1 FROM thongbao WHERE MaTaiKhoan=? AND TieuDe=? AND NgayTao>=DATE_SUB(NOW(),INTERVAL 14 DAY) LIMIT 1");$chk->bind_param('is',$uid,$title);$chk->execute();if(!$chk->get_result()->fetch_assoc()){$in=$conn->prepare("INSERT INTO thongbao(MaTaiKhoan,MaDocGia,TieuDe,NoiDung,Loai,DuongDan) VALUES(?,?,?,?,'info','trangchu.php')");$in->bind_param('iiss',$uid,$rid,$title,$content);$in->execute();}}}
