 $s=$conn->prepare("SELECT * FROM thongbao WHERE MaTaiKhoan=? ORDER BY DaDoc ASC,NgayTao DESC LIMIT 30");$s->bind_param('i',$uid);$s->execute();$rows=aall($s->get_result());$unread=0;foreach($rows as $r)if(!(int)$r['DaDoc'])$unread++;aok(['rows'=>$rows,'unread'=>$unread]);
